window.BloomHelpData.register({"schema":1,"locale":"pl","nativeReviewRequired":true,"common":{"review":"Wersja robocza tłumaczenia. Wymagana weryfikacja przez rodzimego użytkownika języka.","fallback":"Część pomocy jest wyświetlana po angielsku.","recovery":"Gdy coś pójdzie nie tak","availability":"Wersja do integracji; sprawdź obsługę w zatwierdzonej kompilacji."},"routes":{"start":{"title":"Nowa karta / strona startowa","summary":"Otwórz zapisaną witrynę lub wpisz adres.","step":"Wybierz kafelek, a następnie Otwórz. Użyj pola adresu, aby odwiedzić inną witrynę.","recovery":"Jeśli kafelek nie działa, spróbuj znanej działającej strony publicznej i sprawdź połączenie sieciowe."},"passwords":{"title":"Menedżer haseł (prototyp interfejsu; sejf jest natywny)","summary":"Ostrożnie korzystaj z zapisanych danych logowania.","step":"Sprawdź adres witryny przed wybraniem zapisanego konta.","recovery":"Jeśli sejf jest zablokowany, odblokuj go w obsługiwany sposób. Nigdy nie umieszczaj haseł w zgłoszeniu do pomocy technicznej."},"settings":{"title":"Ustawienia","summary":"Dostosuj preferencje przeglądania.","step":"Zmieniaj po jednym ustawieniu i sprawdzaj wynik.","recovery":"Pozostaw eksperymentalne ustawienia JIT i GPU wyłączone, chyba że realizujesz zatwierdzony plan testów."},"https-only":{"title":"Tryb tylko HTTPS"},"private":{"title":"Przeglądanie prywatne"},"themes":{"title":"Wspólne motywy"},"reader":{"title":"Tryb czytania","summary":"Czytaj artykuł z mniejszą liczbą rozpraszających elementów.","step":"Otwórz tryb czytania dla bieżącego artykułu i dostosuj dostępne ustawienia tekstu.","recovery":"Niektórych stron nie można wyodrębnić; wróć do oryginalnej strony, jeśli brakuje treści."},"media":{"title":"Centrum multimediów"},"downloads":{"title":"Panel pobierania","summary":"Śledź pobieranie i zarządzaj nim.","step":"Sprawdź stan i miejsce docelowe każdego zadania; otwieraj pliki dopiero po zakończeniu pobierania.","recovery":"Jeśli zadanie się nie powiedzie, zachowaj komunikat błędu. JDownloader jest opcjonalny i musi przejść kontrole Setup."},"notes":{"title":"Notatki"},"device-login":{"title":"Zaloguj się na innym urządzeniu"},"status":{"title":"Stan Bloom Core","summary":"Sprawdź, które aplikacje pakietu odpowiadają.","step":"Przeczytaj stan każdej aplikacji przed jej otwarciem.","recovery":"Jeśli Bloom Core nie działa, wspólne wykrywanie aplikacji może być niedostępne; zachowaj wyświetlony błąd."},"library":{"title":"Zakładki i historia","summary":"Znajdź zapisane linki i historię przeglądania.","step":"Wybierz Zakładki lub Historia i sprawdź adres przed otwarciem wyniku.","recovery":"Usunięcie lokalnego wpisu nie usuwa konta w witrynie ani jego zapisów."},"translate":{"title":"Przetłumacz stronę","summary":"Czytaj stronę po angielsku.","step":"Sprawdź adres witryny i informację o Google Translate. Kontynuuj tylko wtedy, gdy zgadzasz się wysłać adres strony.","recovery":"Jeśli strona się zmieni, otwórz ponownie ten panel i potwierdź nową stronę. Tłumaczenie może być niedokładne; unikaj przesyłania poufnych treści."}}});
